import sys,csv
rows=list(csv.reader(sys.stdin))
h=rows[0]
# pick first data row that has numeric for a known col
def colidx(name):
    for i,c in enumerate(h):
        if c==name: return i
    return None
# find a data row: row where 'ID' col is integer
iid=colidx('ID')
drow=None
for r in rows[1:]:
    if iid is not None and iid<len(r):
        try: int(r[iid]); drow=r; break
        except: pass
if drow is None: drow=rows[2] if len(rows)>2 else rows[1]
print('=== STALL REASONS (avg warps stalled per issue-active, in inst-cycles) ===')
items=[]
for i,c in enumerate(h):
    if c.startswith('smsp__average_warps_issue_stalled_') and c.endswith('_per_issue_active.ratio'):
        name=c[len('smsp__average_warps_issue_stalled_'):-len('_per_issue_active.ratio')]
        try: v=float(drow[i])
        except: v=0.0
        items.append((v,name))
tot=sum(v for v,_ in items) or 1
for v,name in sorted(items,reverse=True):
    if v>0.001: print(f'  {v:7.3f} ({100*v/tot:5.1f}%)  {name}')
print(f'  TOTAL cyc/inst (sum) = {tot:.3f}')
print()
print('=== PIPE THROUGHPUT (% peak) ===')
pt=[]
for i,c in enumerate(h):
    cl=c.lower()
    if ('inst_executed_pipe' in cl and 'pct_of_peak' in cl) or (cl.startswith('sm__pipe') and 'pct_of_peak' in cl and 'active' in cl):
        try: v=float(drow[i])
        except: v=0.0
        pt.append((v,c))
for v,c in sorted(pt,reverse=True)[:14]:
    if v>0.01: print(f'  {v:7.2f}%  {c}')
"

